import {load,save,record,purchase,skins} from './storage.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let storage;try{storage=window.localStorage}catch{storage=null}
let {data,available}=load(storage);
const games={flappybron:{name:'FlappyBron',file:'flappybron',description:'Tap into your next high score. Fly through the hoops and collect rings along the way.',help:'Space / ↑ / tap to flap · P or Esc to pause',actions:[['primary','FLAP ↑']]},pacbron:{name:'PacBron',file:'pacbron',description:'Collect every basketball. Grab glowing power rings to turn the tables on defenders. Clear all three courts.',help:'Arrow keys or WASD to move · P or Esc to pause',actions:[['left','←'],['up','↑'],['down','↓'],['right','→']]},fighter:{name:'LeBron Fighter',file:'fighter',description:'Face three rivals in the campaign or challenge a friend on the same keyboard. Time your attacks and protect your guard.',help:'P1: A/D move · W jump · S/H block · F punch · G kick. P2: ←/→ move · ↑ jump · ↓/L block · J punch · K kick. P or Esc pauses.',actions:[['left','←'],['up','↑'],['right','→'],['block','BLOCK'],['primary','PUNCH'],['secondary','KICK']]}};
const panel=$('#panel'),dialog=$('#gameDialog'),canvas=$('#gameCanvas'),ctx=canvas.getContext('2d'),overlay=$('#gameOverlay');
let game=null,current=null,phase='closed',difficulty='normal',mode='cpu',raf=0,last=0,accumulator=0,score=0,loadToken=0,audio=null;
const heldKeys=new Map(),heldPointers=new Map(),actionSources=new Map();
function persist(){available=save(storage,data);refresh()}
function best(id){return Math.max(...Object.values(data.stats[id]).map(x=>x.best))}
function refresh(){$('#balance').textContent=data.coins.toLocaleString();$$('[data-best]').forEach(el=>el.textContent=best(el.dataset.best)||'—');$('#soundToggle').textContent=data.sound?'Sound on':'Sound off';$('#soundToggle').setAttribute('aria-pressed',String(data.sound))}
let toastTimer;function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3500)}
function showPanel(type){if(dialog.open)return;let html='';if(type==='records'){html='<div class="eyebrow">YOUR PERSONAL SCOREBOARD</div><h2 id="panelTitle">Chase your own legend.</h2><p>Personal bests on this browser, separated by difficulty. Local versus results are unranked.</p><table class="records"><thead><tr><th>GAME</th><th>EASY</th><th>NORMAL</th><th>HARD</th></tr></thead><tbody>';for(const [id,g]of Object.entries(games))html+=`<tr><td>${g.name}</td>${['easy','normal','hard'].map(d=>`<td>${data.stats[id][d].best.toLocaleString()}</td>`).join('')}</tr>`;html+='</tbody></table><p>Your records are stored on this device. There is no shared online leaderboard.</p>'}else if(type==='how'){html='<div class="eyebrow">PICK UP & PLAY</div><h2 id="panelTitle">Know your moves.</h2>';for(const g of Object.values(games))html+=`<h3>${g.name}</h3><p>${g.description}</p><p>${g.help}</p>`;html+='<h3>Made for your screen</h3><p>Use the buttons below each game on touch screens. Local two-player Fighter needs a shared keyboard. Games pause when you switch tabs. Earn rings from solo games to unlock jerseys in your locker.</p>'}else{html=`<div class="eyebrow">THE LOCKER ROOM</div><h2 id="panelTitle">Wear your era.</h2><p>You have <strong>${data.coins} rings</strong>. Collect rings in FlappyBron, clear courts in PacBron, or win fights to unlock a new look.</p><div class="locker-grid">${skins.map(s=>`<div class="jersey"><div class="jersey-icon" style="background:${s.color}">23</div><p>${s.name}</p><button data-skin="${s.id}" aria-pressed="${data.skin===s.id}" ${!data.unlocked.includes(s.id)&&data.coins<s.cost?'disabled':''}>${data.skin===s.id?'Equipped':data.unlocked.includes(s.id)?'Equip':`${s.cost} rings`}</button></div>`).join('')}</div>`}if(!available)html+='<p class="storage-warning">Browser storage is unavailable. Progress will last only for this session.</p>';$('#panelContent').innerHTML=html;if(!panel.open)panel.showModal();$$('[data-skin]').forEach(b=>b.onclick=()=>{data=purchase(data,b.dataset.skin);persist();showPanel('locker')})}
$$('[data-panel]').forEach(b=>b.onclick=()=>showPanel(b.dataset.panel));$('#closePanel').onclick=()=>panel.close();panel.addEventListener('click',e=>{if(e.target===panel&&outside(e,panel))panel.close()});function outside(e,el){const r=el.getBoundingClientRect();return e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom}
$$('[data-filter]').forEach(b=>b.onclick=()=>{$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b?'true':'false')});$$('[data-game]').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.category!==b.dataset.filter)});
function sound(name){if(!data.sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.connect(gain);gain.connect(audio.destination);osc.type='triangle';osc.frequency.value=({flap:460,score:740,coin:980,win:880,lose:150,hit:190,power:650})[name]||360;gain.gain.setValueAtTime(.045,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.12);osc.start();osc.stop(audio.currentTime+.13)}catch{}}
function releaseAll(){for(const action of actionSources.keys())game?.action(action,false);actionSources.clear();heldKeys.clear();heldPointers.clear()}
function setAction(action,source,down){if(phase!=='playing')return;let sources=actionSources.get(action);if(down){if(!sources){sources=new Set();actionSources.set(action,sources)}if(sources.has(source))return;const first=sources.size===0;sources.add(source);if(first)game?.action(action,true)}else if(sources){sources.delete(source);if(!sources.size){game?.action(action,false);actionSources.delete(action)}}}
function destroy(){cancelAnimationFrame(raf);releaseAll();game?.destroy?.();game=null;accumulator=0;last=0}
function resize(){const r=canvas.getBoundingClientRect();const ratio=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(r.width*ratio));canvas.height=Math.max(1,Math.round(r.height*ratio));draw()}
function draw(){ctx.setTransform(canvas.width/960,0,0,canvas.height/600,0,0);ctx.clearRect(0,0,960,600);if(game)game.draw(ctx,960,600);else{ctx.fillStyle='#1e1532';ctx.fillRect(0,0,960,600);ctx.strokeStyle='#553b71';ctx.lineWidth=3;ctx.strokeRect(80,60,800,480);ctx.beginPath();ctx.arc(480,300,100,0,Math.PI*2);ctx.stroke()}}
function tick(t){if(phase!=='playing')return;if(!last)last=t;accumulator+=Math.min((t-last)/1000,.1);last=t;while(accumulator>=1/60&&phase==='playing'){game.update(1/60);accumulator-=1/60}draw();if(phase==='playing')raf=requestAnimationFrame(tick)}
async function openGame(id){if(!games[id])return;destroy();current=id;phase='setup';score=0;$('#liveScore').textContent=0;$('#gameTitle').textContent=games[id].name;$('#gameBest').textContent=best(id);$('#gameStatus').textContent='Choose your challenge';$('#controlHelp').textContent=games[id].help;$('#pauseGame').disabled=true;$('#pauseGame').textContent='Pause';$('#touchControls').innerHTML='';if(!dialog.open)dialog.showModal();overlay.hidden=false;overlay.innerHTML=`<div class="eyebrow">${id==='fighter'?'THE KING’S COURT':'READY WHEN YOU ARE'}</div><h3>${games[id].name}</h3><p>${games[id].description}</p><div class="options"><label>Difficulty<select id="difficulty"><option value="easy">Easy</option><option value="normal" selected>Normal</option><option value="hard">Hard</option></select></label>${id==='fighter'?'<label>Mode<select id="mode"><option value="cpu">Solo campaign</option><option value="versus">Local 2 player</option></select></label>':''}</div><button id="startGame" class="button primary">LET’S PLAY <span>↗</span></button>`;$('#startGame').onclick=()=>{difficulty=$('#difficulty').value;mode=$('#mode')?.value||'cpu';start()};requestAnimationFrame(resize);}
async function start(){destroy();phase='loading';const token=++loadToken;overlay.hidden=false;overlay.innerHTML='<h3>Warming up…</h3>';try{const module=await import(`./games/${games[current].file}.js`);if(token!==loadToken||!dialog.open)return;phase='playing';score=0;$('#liveScore').textContent='0';game=module.createGame({difficulty,mode,skin:data.skin,updateHUD(v){if(v.score!==undefined){score=v.score;$('#liveScore').textContent=score.toLocaleString()}if(v.status)$('#gameStatus').textContent=v.status},finish,sound});$('#gameBest').textContent=data.stats[current][difficulty].best;overlay.hidden=true;$('#pauseGame').disabled=false;$('#pauseGame').textContent='Pause';touchControls();resize();last=0;raf=requestAnimationFrame(tick);canvas.focus({preventScroll:true});sound('score')}catch(error){phase='error';overlay.innerHTML='<h3>Couldn’t load this game.</h3><p>Check your connection and try again.</p><button id="retry" class="button primary">TRY AGAIN</button>';$('#retry').onclick=start;console.error(error)}}
function finish(result){if(phase!=='playing')return;releaseAll();phase='finished';cancelAnimationFrame(raf);const earned=mode==='versus'?0:Math.max(0,Math.floor(result.coins||0));const previous=data.stats[current][difficulty].best;if(mode!=='versus'){data=record(data,current,difficulty,result.score,earned);persist()}$('#liveScore').textContent=result.score;$('#gameBest').textContent=data.stats[current][difficulty].best;$('#pauseGame').disabled=true;overlay.hidden=false;overlay.innerHTML=`<div class="eyebrow">${mode==='versus'?'LOCAL DUEL':result.score>previous?'NEW PERSONAL BEST':'EVERY RUN IS A NEW CHANCE'}</div><h3>${mode==='versus'?'Final buzzer':Number(result.score).toLocaleString()+' POINTS'}</h3><p id="finishMessage"></p><p>${mode==='versus'?'Friendly match · no ranked score':`+${earned} rings · ${data.coins} in your locker`}</p><div class="overlay-actions"><button id="again" class="button primary">PLAY AGAIN ↗</button><button id="change" class="small-button">CHANGE SETTINGS</button></div>`;$('#finishMessage').textContent=result.message||'Good game. Ready for another?';$('#again').onclick=start;$('#change').onclick=()=>openGame(current);$('#again').focus({preventScroll:true})}
function pause(){if(phase!=='playing')return;releaseAll();phase='paused';cancelAnimationFrame(raf);$('#pauseGame').textContent='Resume';overlay.hidden=false;overlay.innerHTML='<div class="eyebrow">TAKE A BREATHER</div><h3>Timeout.</h3><p>Your game will be right here.</p><button id="resume" class="button primary">BACK IN THE GAME ↗</button>';$('#resume').onclick=resume;$('#resume').focus({preventScroll:true})}
function resume(){if(phase!=='paused')return;phase='playing';overlay.hidden=true;$('#pauseGame').textContent='Pause';last=0;accumulator=0;raf=requestAnimationFrame(tick);canvas.focus({preventScroll:true})}
function closeGame(){loadToken++;destroy();phase='closed';if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>{});dialog.close()}
$('#exitGame').onclick=closeGame;$('#pauseGame').onclick=()=>phase==='playing'?pause():resume();dialog.addEventListener('cancel',e=>{e.preventDefault();if(phase==='playing')pause();else if(phase==='paused')resume();else closeGame()});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});window.addEventListener('blur',pause);window.addEventListener('resize',resize);new ResizeObserver(resize).observe(canvas);
$('#soundToggle').onclick=()=>{data.sound=!data.sound;persist();if(data.sound)sound('score')};$('#fullGame').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(dialog.requestFullscreen)await dialog.requestFullscreen();else toast('Fullscreen is not supported in this browser.')}catch{toast('Fullscreen is unavailable. Try rotating your device.')}};
function mapKey(code){if(current==='flappybron')return ['Space','ArrowUp','KeyW'].includes(code)?'primary':null;if(current==='pacbron')return({ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowUp:'up',KeyW:'up',ArrowDown:'down',KeyS:'down'})[code];return({KeyA:'left',KeyD:'right',KeyW:'up',KeyS:'block',KeyH:'block',KeyF:'primary',KeyG:'secondary',ArrowLeft:'p2left',ArrowRight:'p2right',ArrowUp:'p2up',ArrowDown:'p2block',KeyL:'p2block',KeyJ:'p2primary',KeyK:'p2secondary'})[code]}
window.addEventListener('keydown',e=>{if(!dialog.open||e.target.matches('select,input,textarea'))return;if(e.code==='KeyP'&&!e.repeat){e.preventDefault();phase==='playing'?pause():resume();return}if(phase!=='playing')return;const a=mapKey(e.code);if(a){e.preventDefault();if(!e.repeat){heldKeys.set(e.code,a);setAction(a,e.code,true)}}});window.addEventListener('keyup',e=>{const a=heldKeys.get(e.code);if(a){setAction(a,e.code,false);heldKeys.delete(e.code)}});
function bindPointer(el,action){el.addEventListener('pointerdown',e=>{if(phase!=='playing')return;e.preventDefault();el.setPointerCapture(e.pointerId);heldPointers.set(e.pointerId,action);setAction(action,'pointer'+e.pointerId,true)});for(const type of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(type,e=>{const a=heldPointers.get(e.pointerId);if(a){setAction(a,'pointer'+e.pointerId,false);heldPointers.delete(e.pointerId)}})}
function touchControls(){const controls=games[current].actions;$('#touchControls').innerHTML=current==='flappybron'?'<button data-action="primary" class="flap-button">TAP TO FLAP ↑</button>':`<div>${controls.slice(0,current==='fighter'?3:4).map(([a,t])=>`<button data-action="${a}" aria-label="${a}">${t}</button>`).join('')}</div>${current==='fighter'?`<div>${controls.slice(3).map(([a,t])=>`<button data-action="${a}">${t}</button>`).join('')}</div>`:''}`;$$('[data-action]').forEach(b=>bindPointer(b,b.dataset.action))}
canvas.addEventListener('pointerdown',e=>{if(current!=='flappybron'||phase!=='playing')return;e.preventDefault();canvas.setPointerCapture(e.pointerId);heldPointers.set(e.pointerId,'primary');setAction('primary','pointer'+e.pointerId,true)});for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,e=>{const a=heldPointers.get(e.pointerId);if(a){setAction(a,'pointer'+e.pointerId,false);heldPointers.delete(e.pointerId)}});
$$('[data-play]').forEach(b=>b.onclick=()=>openGame(b.dataset.play));$('#randomGame').onclick=()=>openGame(Object.keys(games)[Math.floor(Math.random()*3)]);refresh();
// Keep legacy game links useful without duplicating the game engines.
const requested=new URLSearchParams(location.search).get('game');if(games[requested])openGame(requested);
